import { DomainError } from "./DomainError";

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
}

export function createOrderLine(productId: string, quantity: number): OrderLine {
  if (productId.trim() === "") {
    throw new DomainError("invalid", "Product id must not be empty");
  }
  if (!Number.isInteger(quantity) || quantity <= 0) {
    throw new DomainError("invalid", `Quantity for ${productId} must be a positive integer`);
  }
  return { productId, quantity };
}

